import{_ as a,a as t,c as n,ac as r}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 43 Are there strangers in space?","description":"学习 there be 与存在命题，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 43 Are there strangers in space?","description":"学习 there be 与存在命题，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 there be 与存在命题，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 42 Recording an earthquake","link":"/life/english/new-concept/book-4/unit-06/lesson-042"},"next":{"text":"第四册：流利英语 · Lesson 44 Patterns of culture","link":"/life/english/new-concept/book-4/unit-06/lesson-044"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 42 Recording an earthquake","link":"/life/english/new-concept/book-4/unit-06/lesson-042"},"next":{"text":"第四册：流利英语 · Lesson 44 Patterns of culture","link":"/life/english/new-concept/book-4/unit-06/lesson-044"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-06/lesson-043.md","filePath":"life/english/new-concept/book-4/unit-06/lesson-043.md"}'),i={name:"life/english/new-concept/book-4/unit-06/lesson-043.md"};function o(l,e,s,h,d,c){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="第四册-流利英语-·-lesson-43-are-there-strangers-in-space" tabindex="-1">第四册：流利英语 · Lesson 43 Are there strangers in space? <a class="header-anchor" href="#第四册-流利英语-·-lesson-43-are-there-strangers-in-space" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 43 Are there strangers in space?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元 6</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕地外生命问题训练证据等级阅读，区分尚未探测到、没有证据和已经证明不存在。讨论可能性时说明依据与搜索范围，不把大数量推算直接变成发现声明。重点掌握存在句与复杂后置修饰，使未知问题的表达清楚而不夸大确定性。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>signal</td><td>/ˈsɪɡnəl/</td><td>n.</td><td>信号</td><td>a candidate signal</td></tr><tr><td>possibility</td><td>/ˌpɒsəˈbɪləti/</td><td>n.</td><td>可能性</td><td>a remote possibility</td></tr><tr><td>detection</td><td>/dɪˈtekʃən/</td><td>n.</td><td>探测</td><td>a confirmed detection</td></tr><tr><td>alternative</td><td>/ɔːlˈtɜːnətɪv/</td><td>n.</td><td>另一解释或选择</td><td>an alternative explanation</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>search for — 寻找某对象</li><li>as yet — 到目前为止</li></ul><h2 id="语法讲解-there-be-与存在命题" tabindex="-1">语法讲解：there be 与存在命题 <a class="header-anchor" href="#语法讲解-there-be-与存在命题" aria-label="Permalink to &quot;语法讲解：there be 与存在命题&quot;">​</a></h2><p>there be 用来引入某处或某情境中存在的事物，there 不表示实际地点；谓语通常与后面的名词一致。There may be an alternative explanation. 表示可能存在解释，不保证解释为真。there is no evidence that… 意为没有支持该命题的证据，不自动等于该命题已被证明为假。避免 there have 代替 there be；若强调某人拥有物品，改用 have 的普通主谓结构。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>There may be a simpler explanation for the unusual signal.</p></blockquote><p>这个异常信号可能有一种更简单的解释。</p><p>there may be 为情态存在结构；a simpler explanation 是引入的新信息；for…限定解释对象。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>There have a signal 不成立；应写 There is a signal 或 The receiver has detected a signal。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>读 There may be 时不要把 may 弱化到听不见；重读 simpler explanation，使谨慎语气明确。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The receiver detected an unusual pattern. There may be an explanation within the instrument itself. Independent observations are needed before we attribute the signal to an external source.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句评价虚构异常信号：观察、替代解释、验证需求。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>从观察到解释保留推理间隔，先检验设备来源，避免把异常等同于发现。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>填空：There ___ two possible explanations in the report.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> are</p><p><strong>解析：</strong> 正式书面语中 be 与后面的复数名词一致。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>示例是否声称已经找到了更简单解释？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 没有。</p><p><strong>解析：</strong> may be 只表示可能存在。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>“没有支持X的证据”是否必然等于“已证明非X”？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 不必然。</p><p><strong>解析：</strong> 还需考虑搜索范围、证据能力与反证。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：there be 与存在命题。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-06/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-06/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-06/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-06/lesson-042">上一课</a> · <a href="/life/english/new-concept/book-4/unit-06/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-06/lesson-044">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",o]]);export{u as __pageData,b as default};
